mapper.select:
SELECT id, user_id, category_id, prompt_type, prompt_style, prompt_text, image_url, image_aspect_ratio, purpose, additional_notes, text_content, init_regi_pic, init_regi_dttm, final_rvis_pic, final_rvis_dttm FROM prompt_history
AND init_regi_pic = #{loginId}
AND prompt_type = #{promptType}
AND prompt_style = #{promptStyle}
AND init_regi_dttm >= #{dateFrom}::date
AND init_regi_dttm < #{dateTo}::date + INTERVAL '1 day'
ORDER BY init_regi_dttm DESC

SELECT COUNT(*)  >  0
FROM prompt_history
WHERE category_id = #{categoryId}
